export default {"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"color-scheme\" content=\"dark\"><meta name=\"description\" content=\"Private usage statistics for 3DSRP.\">\n<title>3DSRP · Usage dashboard</title><link rel=\"icon\" href=\"/portal.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"><script src=\"/app.js\" defer></script>\n</head>\n<body>\n<header class=\"masthead\"><div class=\"brand\"><img src=\"/portal.svg\" width=\"42\" height=\"42\" alt=\"\"><div><span class=\"wordmark\">3DSRP</span><span class=\"brand-sub\">AURORASTUDIOS84</span></div></div><div class=\"header-right\"><span class=\"private-badge\"><span></span> Private dashboard</span><a class=\"signout\" href=\"/cdn-cgi/access/logout\">Sign out <span aria-hidden=\"true\">↗</span></a></div></header>\n<main>\n<section class=\"intro\"><div><p class=\"eyebrow\">USAGE OVERVIEW</p><h1>Your homebrew,<br class=\"mobile-break\"> out in the world.</h1><p class=\"intro-copy\">See how much each 3DSRP app is being played.</p></div><div class=\"update-block\"><span id=\"last-updated\">Waiting for statistics</span><button id=\"refresh\" class=\"button secondary\" type=\"button\"><span aria-hidden=\"true\">↻</span> Refresh</button></div></section>\n<form id=\"filters\" class=\"filters\"><div class=\"range-presets\" aria-label=\"Date range\"><button type=\"button\" data-days=\"7\">7 days</button><button type=\"button\" data-days=\"30\" class=\"active\" aria-pressed=\"true\">30 days</button><button type=\"button\" data-days=\"90\">90 days</button></div><label class=\"app-filter\">App<select id=\"app\"><option value=\"all\">All apps</option><option value=\"new_3ds\">New 3DS</option><option value=\"original_3ds\">Original 3DS Relay</option></select></label><div class=\"dates\"><label>From<input type=\"date\" id=\"from\" required></label><span class=\"date-arrow\" aria-hidden=\"true\">→</span><label>To<input type=\"date\" id=\"to\" required></label><button class=\"button apply\" type=\"submit\">Apply</button></div></form>\n<p id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\">Loading your usage statistics…</p>\n<section class=\"metrics\" aria-label=\"Usage summary\" aria-busy=\"true\" id=\"metrics\"><article class=\"metric\"><p>Reporting installations</p><div id=\"metric-installations\" class=\"metric-value\">—</div><span>Distinct app installations</span></article><article class=\"metric\"><p>Time streamed</p><div id=\"metric-time\" class=\"metric-value\">—</div><span>Across the selected dates</span></article><article class=\"metric\"><p>Sessions started</p><div id=\"metric-sessions\" class=\"metric-value\">—</div><span>Counted once per session</span></article><article class=\"metric\"><p>Time per installation</p><div id=\"metric-average\" class=\"metric-value\">—</div><span>Average for this period</span></article></section>\n<section class=\"panel activity\"><div class=\"panel-heading\"><div><h2>Daily activity</h2><p id=\"chart-subtitle\">Streamed time by activity date</p></div><div class=\"chart-controls\" role=\"group\" aria-label=\"Chart metric\"><button class=\"active\" type=\"button\" data-chart=\"seconds\" aria-pressed=\"true\">Time</button><button type=\"button\" data-chart=\"sessions\" aria-pressed=\"false\">Sessions</button></div></div><div class=\"chart-wrap\"><div id=\"chart\" class=\"chart\" role=\"img\" aria-label=\"Daily usage chart\"></div><div id=\"chart-tooltip\" class=\"chart-tooltip\" role=\"status\" hidden></div><div id=\"chart-empty\" class=\"chart-empty\" hidden>No reported activity in this period.</div></div><div class=\"chart-footer\"><span><i></i> <span id=\"chart-legend\">Time streamed</span></span><span id=\"range-label\"></span></div></section>\n<section class=\"panel installations\"><div class=\"panel-heading\"><div><h2>Installations <span id=\"installation-count\" class=\"count-pill\">—</span></h2><p>Find the regulars, the newcomers, and everyone in between.</p></div><button id=\"export\" class=\"button secondary\" type=\"button\"><span aria-hidden=\"true\">↓</span> Export CSV</button></div><div class=\"table-toolbar\"><label class=\"search\"><span aria-hidden=\"true\">⌕</span><input id=\"search\" type=\"search\" placeholder=\"Search installation ID…\" aria-label=\"Search installation ID\" autocomplete=\"off\" spellcheck=\"false\"><kbd>/</kbd></label><label class=\"sort\">Sort by <select id=\"sort\"><option value=\"time\">Most time played</option><option value=\"sessions\">Most sessions</option><option value=\"recent\">Last active</option></select></label></div><div class=\"table-scroll\"><table><thead><tr><th scope=\"col\">App</th><th scope=\"col\">Installation ID</th><th scope=\"col\">Time streamed</th><th scope=\"col\">Sessions</th><th scope=\"col\">First active</th><th scope=\"col\">Last active</th><th scope=\"col\"><span class=\"sr-only\">Details</span></th></tr></thead><tbody id=\"installation-rows\"></tbody></table></div><div id=\"table-empty\" class=\"table-empty\" hidden>No installations match these filters.</div><div class=\"pagination\"><span id=\"page-label\">—</span><div><button id=\"previous\" class=\"button icon\" type=\"button\" aria-label=\"Previous page\" disabled>←</button><button id=\"next\" class=\"button icon\" type=\"button\" aria-label=\"Next page\" disabled>→</button></div></div></section>\n<footer><p><span class=\"footer-dot\"></span> Opt-in statistics. App installations aren’t people.</p><p>Installation history is retained for 90 days. Dates follow each 3DS clock.</p></footer>\n</main>\n<dialog id=\"details\"><div class=\"detail-head\"><div><p class=\"eyebrow\">INSTALLATION DETAILS</p><h2>Activity by day</h2></div><button id=\"close-details\" class=\"button icon\" aria-label=\"Close installation details\">×</button></div><code id=\"detail-id\"></code><p id=\"detail-status\" class=\"status\" role=\"status\"></p><div class=\"table-scroll\"><table><thead><tr><th>App</th><th>Date</th><th>Time streamed</th><th>Sessions started</th></tr></thead><tbody id=\"detail-rows\"></tbody></table></div><p class=\"detail-note\">Within the selected date range. A session crossing midnight counts once on its earliest reported day.</p></dialog>\n</body></html>\n"},"/style.css":{"type":"text/css; charset=utf-8","body":":root{color-scheme:dark;--bg:#080e1b;--panel:#101a2c;--line:#22314a;--muted:#94a5c0;--blue:#6caaff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 70% 0,#142849 0,transparent 45%),var(--bg);color:#eef4ff;font:15px/1.5 system-ui,sans-serif}button,input,select{font:inherit}button,a,input,select{outline-offset:4px}button{cursor:pointer}button:disabled{opacity:.35;cursor:default}a{color:var(--blue)}.masthead,main{max-width:1280px;margin:auto;padding:30px 40px}.masthead,.brand,.header-right,.intro,.filters,.dates,.panel-heading,.table-toolbar,.pagination,.detail-head{display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{justify-content:start;gap:12px}.wordmark{display:block;font-size:23px;font-weight:800;letter-spacing:2px}.brand-sub{display:block;font-size:9px;letter-spacing:2px;color:var(--muted)}.private-badge{font-size:12px;border:1px solid var(--line);border-radius:30px;padding:7px 12px}.private-badge span,.footer-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#67d3ae;margin-right:6px}.signout{font-size:13px;text-decoration:none;color:var(--muted)}main{padding-top:28px}.intro{margin-bottom:32px}.eyebrow{font-size:11px;letter-spacing:2px;color:var(--blue);font-weight:700}h1{font-size:clamp(30px,4vw,45px);line-height:1.2;letter-spacing:-1.5px;margin:12px 0}h2{font-size:19px;margin:0}.intro-copy,.panel-heading p{color:var(--muted);margin:9px 0 0}.update-block{text-align:right;display:grid;gap:10px;justify-items:end;font-size:11px;color:var(--muted)}.button,.range-presets button,.chart-controls button{border:1px solid var(--line);border-radius:8px;padding:9px 15px;color:#d9e5fa;background:#17243a}.button.secondary{background:transparent}.button.apply{background:#4289ee;color:white;border-color:#4289ee;align-self:end}.filters{background:#0e182a;border:1px solid var(--line);border-radius:12px;padding:16px}.range-presets,.chart-controls{display:flex;gap:4px}.range-presets button,.chart-controls button{background:transparent;border-color:transparent;color:var(--muted);white-space:nowrap}.range-presets button.active,.chart-controls button.active{background:#223b60;color:#b8d8ff}.dates{gap:12px}label{color:var(--muted);font-size:11px}input,select{color:#e9f1ff;background:#101b2e;border:1px solid var(--line);border-radius:7px;padding:8px}input[type=date]{display:block;margin-top:4px;min-width:140px}.date-arrow{padding-top:18px;color:var(--muted)}.status{font-size:13px;min-height:20px;color:var(--muted);margin:15px 0}.status.error{color:#ffb4b4}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:20px 0 26px}.metric,.panel{background:linear-gradient(120deg,#121f34,#0e1829);border:1px solid var(--line);border-radius:13px}.metric{padding:21px}.metric p{margin:0;color:#bdcbe0;font-size:12px}.metric-value{font-size:33px;font-weight:650;letter-spacing:-1px;margin:12px 0 6px}.metric span{font-size:11px;color:var(--muted)}.panel{margin-bottom:24px;padding:24px}.panel-heading p{font-size:12px}.chart-wrap{position:relative;min-height:240px;margin-top:24px}.chart svg{width:100%;height:240px;overflow:visible}.chart svg text{fill:#8d9eba;font:11px system-ui}.chart svg .grid{stroke:#23324a;stroke-width:1}.chart svg .bar{fill:#579bf5;rx:3}.chart svg .bar:hover,.chart svg .bar:focus{fill:#a5d2ff;outline:none}.chart-tooltip{position:absolute;left:50%;top:0;transform:translateX(-50%);background:#203653;border:1px solid #597eaf;border-radius:6px;padding:7px 12px;font-size:12px;pointer-events:none;white-space:nowrap}.chart-empty{position:absolute;inset:50% 0 auto;text-align:center;color:var(--muted);font-size:13px}.chart-footer{display:flex;justify-content:space-between;color:var(--muted);font-size:11px;border-top:1px solid var(--line);padding-top:15px}.chart-footer i{display:inline-block;width:8px;height:8px;background:#579bf5;border-radius:2px;margin-right:5px}.count-pill{font-size:11px;color:var(--blue);background:#213854;padding:3px 8px;border-radius:20px;vertical-align:middle;margin-left:6px}.table-toolbar{margin:24px 0 18px}.search{display:flex;align-items:center;gap:10px;border:1px solid var(--line);border-radius:8px;padding:0 10px;width:350px}.search input{border:0;background:none;min-width:0;width:100%;font-size:12px}.search span{font-size:22px}.search kbd{border:1px solid var(--line);padding:0 5px}.sort{display:flex;align-items:center;gap:8px}.sort select{font-size:12px}.table-scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;white-space:nowrap;text-align:left}th{font-size:10px;text-transform:uppercase;letter-spacing:.6px;color:var(--muted);font-weight:500;padding:12px 10px;border-bottom:1px solid var(--line)}td{padding:17px 10px;border-bottom:1px solid #1b2a40;font-size:12px}.id-button{font:11px ui-monospace,monospace;color:#a6caff;background:none;border:0;padding:0;cursor:pointer;text-align:left}.detail-button{background:none;border:0;color:var(--blue)}.table-empty{text-align:center;padding:35px;color:var(--muted)}.pagination{font-size:11px;color:var(--muted);padding-top:18px}.pagination>div{display:flex;gap:8px}.icon{padding:5px 12px;font-size:18px}footer{display:flex;justify-content:space-between;gap:20px;font-size:10px;color:var(--muted);padding:4px 0 30px}dialog{background:#101b2e;color:#edf4ff;border:1px solid #3a5072;border-radius:15px;padding:26px;width:min(650px,calc(100% - 28px));max-height:85vh}dialog::backdrop{background:#030816cc;backdrop-filter:blur(5px)}#detail-id{display:block;overflow-wrap:anywhere;color:var(--blue);margin-top:20px;font-size:12px}.detail-note{font-size:11px;color:var(--muted)}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.mobile-break{display:none}[hidden]{display:none!important}@media(max-width:850px){.masthead,main{padding:22px}.filters{align-items:start;flex-direction:column}.dates{width:100%;justify-content:start}.metrics{grid-template-columns:repeat(2,1fr)}footer{flex-direction:column;gap:0}.private-badge{display:none}}@media(max-width:520px){.masthead,main{padding:18px}.intro{align-items:start;gap:12px}.intro h1{font-size:31px}.mobile-break{display:block}.intro-copy{font-size:12px}.update-block{max-width:95px}.metrics{gap:10px}.metric{padding:15px}.metric-value{font-size:27px}.metric span{font-size:10px}.dates{gap:7px;flex-wrap:wrap}.dates input{min-width:0;width:128px;font-size:12px}.date-arrow{display:none}.filters{padding:12px}.panel{padding:16px}.panel-heading{gap:10px;align-items:start}.panel-heading p{font-size:11px}.panel-heading .button{font-size:11px;padding:8px;white-space:nowrap}.table-toolbar{align-items:stretch;flex-direction:column;gap:10px}.search{width:100%}.sort{justify-content:space-between}.chart-controls button{font-size:11px;padding:6px}.chart-footer{font-size:10px}.signout{font-size:11px}}\n.table-scroll{position:relative}.chart{min-width:0}\n\n.filters{flex-wrap:wrap}.app-filter{display:grid;gap:4px;min-width:180px}.app-filter select{width:100%}.app-name{white-space:nowrap;color:#b8d8ff;font-size:12px}\n"},"/app.js":{"type":"text/javascript; charset=utf-8","body":"'use strict';\nconst $=id=>document.getElementById(id), DAY=86400000;\nconst iso=t=>new Date(t).toISOString().slice(0,10), number=n=>new Intl.NumberFormat().format(n);\nconst duration=s=>s>=3600?`${Math.floor(s/3600)}h ${Math.floor(s%3600/60)}m`:s>=60?`${Math.floor(s/60)}m ${Math.floor(s%60)}s`:`${Math.floor(s)}s`;\nconst appLabel=app=>app==='original_3ds'?'Original 3DS Relay':'New 3DS';\nconst shortDate=d=>new Date(d+'T12:00:00Z').toLocaleDateString(undefined,{month:'short',day:'numeric',timeZone:'UTC'});\nlet page=1, daily=[], chartMetric='seconds', requestGeneration=0, tableGeneration=0, detailGeneration=0;\nlet applied={from:iso(Date.now()-29*DAY),to:iso(Date.now()),app:'all'};\n$('from').value=applied.from;$('to').value=applied.to;\nfunction query(){return new URLSearchParams({...applied,search:$('search').value.trim(),sort:$('sort').value,page:String(page)});}\nfunction status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}\nasync function api(path){const response=await fetch(path,{cache:'no-store'});if(response.status===403)throw Error('Your sign-in has expired. Reload this page to sign in.');const data=await response.json();if(!response.ok)throw Error(data.error||'Unable to load statistics. Please try again.');return data;}\nfunction cell(row,text,className){const td=document.createElement('td');td.textContent=text;if(className)td.className=className;row.append(td);return td;}\nasync function loadTable(){const generation=++tableGeneration;const data=await api('/api/installations?'+query());if(generation!==tableGeneration)return;const body=$('installation-rows');body.replaceChildren();for(const item of data.rows){const row=document.createElement('tr');cell(row,appLabel(item.app),'app-name');const id=cell(row,'');const button=document.createElement('button');button.className='id-button';button.textContent=item.installation_id;button.addEventListener('click',()=>details(item.installation_id,item.app));id.append(button);cell(row,duration(item.seconds));cell(row,number(item.sessions));cell(row,shortDate(item.first_seen));cell(row,shortDate(item.last_seen));const more=document.createElement('button');more.className='detail-button';more.textContent='↗';more.setAttribute('aria-label','View details for '+item.installation_id);more.onclick=()=>details(item.installation_id,item.app);cell(row,'').append(more);body.append(row);}$('installation-count').textContent=number(data.total);$('table-empty').hidden=!!data.total;$('page-label').textContent=data.total?`${number((page-1)*data.page_size+1)}–${number(Math.min(page*data.page_size,data.total))} of ${number(data.total)} installations`:'0 installations';$('previous').disabled=page<=1;$('next').disabled=page*data.page_size>=data.total;}\nasync function refresh(){const generation=++requestGeneration;status('Loading your usage statistics…');$('refresh').disabled=true;$('metrics').setAttribute('aria-busy','true');try{const [data]=await Promise.all([api('/api/overview?'+new URLSearchParams(applied)),loadTable()]);if(generation!==requestGeneration)return;const s=data.summary;$('metric-installations').textContent=number(s.installations);$('metric-time').textContent=duration(s.seconds);$('metric-sessions').textContent=number(s.sessions);$('metric-average').textContent=duration(s.average_installation_seconds);for(const id of ['from','to']){$(id).min=data.range.earliest;$(id).max=data.range.latest;}daily=[];const map=new Map(data.daily.map(d=>[d.day,d]));for(let t=Date.parse(applied.from);t<=Date.parse(applied.to);t+=DAY){const day=iso(t);daily.push(map.get(day)||{day,seconds:0,sessions:0});}drawChart();$('last-updated').textContent='Updated '+new Date(data.updated_at).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});$('range-label').textContent=`${shortDate(applied.from)} – ${shortDate(applied.to)}`;status('');}catch(error){if(generation===requestGeneration)status(error.message,true);}finally{if(generation===requestGeneration){$('refresh').disabled=false;$('metrics').setAttribute('aria-busy','false');}}}\nfunction svg(tag,attrs,text){const el=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))el.setAttribute(k,v);if(text!==undefined)el.textContent=text;return el;}\nfunction drawChart(){const canvasWidth=Math.max(300,$('chart').clientWidth);const root=svg('svg',{viewBox:`0 0 ${canvasWidth} 240`,'aria-label':chartMetric==='seconds'?'Daily time streamed':'Daily sessions started'});const max=Math.max(1,...daily.map(d=>d[chartMetric]));for(let i=0;i<=4;i++){const y=20+i*45;root.append(svg('line',{x1:62,y1:y,x2:canvasWidth-5,y2:y,class:'grid'}));root.append(svg('text',{x:52,y:y+4,'text-anchor':'end'},chartMetric==='seconds'?duration(max*(4-i)/4):String(Math.round(max*(4-i)/4))));}const width=(canvasWidth-70)/Math.max(daily.length,1);daily.forEach((d,i)=>{const height=d[chartMetric]/max*180;const bar=svg('rect',{x:65+i*width,y:200-height,width:Math.max(2,width*.65),height:Math.max(height,1),class:'bar',tabindex:'0',role:'img','aria-label':`${d.day}: ${duration(d.seconds)}, ${d.sessions} sessions`});const label=`${shortDate(d.day)} · ${chartMetric==='seconds'?duration(d.seconds):number(d.sessions)+' sessions'}`;bar.append(svg('title',{},label));const show=()=>{$('chart-tooltip').textContent=label;$('chart-tooltip').hidden=false;};const hide=()=>{$('chart-tooltip').hidden=true;};bar.addEventListener('mouseenter',show);bar.addEventListener('focus',show);bar.addEventListener('mouseleave',hide);bar.addEventListener('blur',hide);root.append(bar);if(i%Math.max(1,Math.ceil(daily.length/(canvasWidth<500?3:6)))===0)root.append(svg('text',{x:65+i*width,y:226,'text-anchor':'start'},shortDate(d.day)));});$('chart').replaceChildren(root);$('chart-empty').hidden=daily.some(d=>d[chartMetric]>0);$('chart-legend').textContent=chartMetric==='seconds'?'Time streamed':'Sessions started';$('chart-subtitle').textContent=chartMetric==='seconds'?'Streamed time by activity date':'Sessions started by activity date';}\nasync function details(id,app){const generation=++detailGeneration;$('detail-id').textContent=appLabel(app)+' · '+id;$('detail-rows').replaceChildren();$('detail-status').textContent='Loading activity…';if(!$('details').open)$('details').showModal();try{const data=await api('/api/installation/'+encodeURIComponent(id)+'?'+new URLSearchParams({...applied,app}));if(generation!==detailGeneration)return;for(const item of data.rows){const row=document.createElement('tr');cell(row,appLabel(item.app));cell(row,item.day);cell(row,duration(item.seconds));cell(row,number(item.sessions));$('detail-rows').append(row);}$('detail-status').textContent=data.rows.length?'':'No reported activity in this date range.';}catch(error){if(generation===detailGeneration)$('detail-status').textContent=error.message;}}\n$('app').onchange=()=>{applied={...applied,app:$('app').value};page=1;refresh();};\n$('close-details').onclick=()=>$('details').close();$('refresh').onclick=refresh;\n$('filters').onsubmit=e=>{e.preventDefault();if($('from').value>$('to').value){status('The start date must be before the end date.',true);return;}applied={from:$('from').value,to:$('to').value,app:$('app').value};page=1;document.querySelectorAll('[data-days]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});refresh();};\ndocument.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{applied={from:iso(Date.now()-(Number(b.dataset.days)-1)*DAY),to:iso(Date.now()),app:$('app').value};$('from').value=applied.from;$('to').value=applied.to;page=1;document.querySelectorAll('[data-days]').forEach(other=>{other.classList.toggle('active',other===b);other.setAttribute('aria-pressed',String(other===b));});refresh();});\ndocument.querySelectorAll('[data-chart]').forEach(b=>b.onclick=()=>{chartMetric=b.dataset.chart;document.querySelectorAll('[data-chart]').forEach(other=>{other.classList.toggle('active',other===b);other.setAttribute('aria-pressed',String(other===b));});drawChart();});\nlet timer;function tableChange(){page=1;loadTable().catch(e=>status(e.message,true));}$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(tableChange,300);};$('sort').onchange=tableChange;$('previous').onclick=()=>{page--;loadTable().catch(e=>status(e.message,true));};$('next').onclick=()=>{page++;loadTable().catch(e=>status(e.message,true));};document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$('details').open){e.preventDefault();$('search').focus();}});\n$('export').onclick=async()=>{$('export').disabled=true;try{const response=await fetch('/api/export.csv?'+query());if(!response.ok){if(response.status===403)throw Error('Reload this page to sign in.');throw Error((await response.json()).error);}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=`3dsrp-usage-${applied.app}-${applied.from}-to-${applied.to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){status(e.message,true);}finally{$('export').disabled=false;}};\nrefresh();\n\nnew ResizeObserver(()=>{if(daily.length)drawChart();}).observe($('chart'));\n"},"/portal.svg":{"type":"image/svg+xml","body":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 48 48\"><rect width=\"48\" height=\"48\" rx=\"13\" fill=\"#10213d\"/><path d=\"M10 40V22a14 14 0 0128 0v18z\" fill=\"none\" stroke=\"#4591ff\" stroke-width=\"3\"/><path d=\"M16 35V23a8 8 0 0116 0v12z\" fill=\"none\" stroke=\"#a7cfff\" stroke-width=\"2\"/><path d=\"M21 31v-8a3 3 0 016 0v8z\" fill=\"#edf5ff\"/></svg>\n"}};
